(()=>{
'use strict';
const panel=document.createElement('aside');panel.className='dev-panel';panel.innerHTML=`<details open><summary>개발자 모드 <small>일반 플레이 저장과 분리</small></summary><div class="dev-controls"><label>주인공 이름<input id="dev-name" maxlength="16" value="검토자"></label><label>허니 호칭<select id="dev-address"><option value="">아직 묻지 않음</option><option value="formal">존칭 유지</option><option value="casual">편한 호칭 허용</option></select></label><label>멤버<select id="dev-person">${CAST.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>장면<select id="dev-scene">${Array.from({length:8},(_,i)=>`<option value="${i}">${i+1}화</option>`).join('')}<option value="date0">외출 1</option><option value="date1">외출 2</option><option value="gift">선물</option><option value="good">연애 결말</option><option value="normal">우정 결말</option><option value="map">8화 완료한 동네</option></select></label><label>친밀도<input id="dev-bond" type="number" min="0" max="100" value="90"></label><button id="dev-go">장면 시작 / 다시 시작</button><button id="dev-back">한 단계 이전</button><button id="dev-skip">선택지까지</button><label><input id="dev-auto" type="checkbox"> 자동 넘김 (3초, 선택지에서 멈춤)</label><a href="script-reader.html">전체 대본</a><a href="index.html">일반 게임</a></div><details><summary>이전 회차 선택 설정</summary><p>설정을 고른 뒤 ‘장면 시작’을 누르면 반영됩니다. 지나간 회차의 선택만 사용합니다.</p><div id="dev-branches"></div></details><p id="dev-status" role="status"></p></details>`;document.body.prepend(panel);
const q=s=>panel.querySelector(s),undo=[];let autoplay=null;
function stop(){clearInterval(autoplay);autoplay=null;q('#dev-auto').checked=false;}
function branchControls(){const c=G.byId(q('#dev-person').value);q('#dev-branches').innerHTML=c.events.map((e,i)=>`<label>${i+1}화 · ${esc(e[0])}<select data-episode="${i}"><option value="">선택 기록 없음</option>${[4,5].map(k=>`<option value="${e[k][1]}">${esc(e[k][0])}</option>`).join('')}</select></label>`).join('');}
const baseAction=action;action=function(a,id,b){if(state&&!$('#modal').open&&['next','choose','pet-name','ending-next','ending-prev'].includes(a))undo.push(JSON.parse(JSON.stringify(state)));return baseAction(a,id,b);};
function start(){stop();close();undo.length=0;const c=G.byId(q('#dev-person').value),v=q('#dev-scene').value;state=G.fresh(q('#dev-name').value);if(q('#dev-address').value)state.honeyAddress=q('#dev-address').value;state.turn=c.hours[0];state.money=100000;const bond=Number(q('#dev-bond').value);state.affinity[c.id]=Math.max(0,Math.min(100,Number.isFinite(bond)?bond:90));const n=/^\d$/.test(v)?Number(v):8;state.progress[c.id]=n;
for(const s of panel.querySelectorAll('[data-episode]'))if(Number(s.dataset.episode)<n&&s.value!=='')state.choices[c.id][Number(s.dataset.episode)]=Number(s.value);
let ok=true;
if(/^\d$/.test(v))ok=G.visit(state,c.id);
else if(v.startsWith('date')){state.dates[c.id]=Number(v.slice(-1));ok=G.outing(state,c.id);}
else if(v==='gift'){const m=window.GIFT_MEMORIES[c.id];state.log.push({speaker:c.name,text:m.quote,characterId:c.id,day:1,sceneTitle:c.events[0][0],sceneTurn:0});ok=G.gift(state,c.id,m.id);}
else if(v==='good'||v==='normal'){state.affinity[c.id]=v==='good'?Math.max(90,state.affinity[c.id]):Math.min(89,state.affinity[c.id]);ok=G.finish(state,c.id);}
screen='map';persist();render();q('#dev-status').textContent=ok?`${c.name} · ${q('#dev-scene').selectedOptions[0].textContent} 시작. 분기·선물용 기록과 진행도는 검토용으로 설정했습니다.`:'장면을 시작하지 못했습니다.';}
q('#dev-person').addEventListener('change',branchControls);q('#dev-go').onclick=start;
q('#dev-back').onclick=()=>{stop();if(!undo.length){q('#dev-status').textContent='이 장면에서 되돌릴 진행이 아직 없습니다.';return;}close();state=undo.pop();screen=state.ending?'ending':state.scene?'scene':'map';persist();render();};
q('#dev-skip').onclick=()=>{stop();close();const sc=state?.scene;if(!sc?.choice){q('#dev-status').textContent='현재 장면에는 남은 선택지가 없습니다.';return;}undo.push(JSON.parse(JSON.stringify(state)));let guard=0;while(state.scene===sc&&sc.step<sc.lines.length&&guard++<100)G.next(state);persist();render();};
q('#dev-auto').onchange=()=>{if(!q('#dev-auto').checked){stop();return;}autoplay=setInterval(()=>{if($('#modal').open)return;const sc=state?.scene;if(!sc||sc.step>=sc.lines.length){stop();return;}action('next');},3000);};
window.addEventListener('pagehide',stop);branchControls();start();
})();